-- Migration V12: Add predictions table for ML model forecast storage
--
-- This table stores hotspot predictions generated by the Prophet + XGBoost
-- hybrid model running in the ML service. Each row represents a single
-- grid cell prediction at a specific forecast time.
--
-- Used for:
--   1. Historical analysis of prediction accuracy
--   2. Audit trail of all generated predictions
--   3. Offline fallback for frontend when ML service is unreachable
--   4. Trend analysis over time

CREATE TABLE IF NOT EXISTS predictions (
    id                  VARCHAR(36) PRIMARY KEY,
    cell_lat            DOUBLE PRECISION NOT NULL,
    cell_lng            DOUBLE PRECISION NOT NULL,
    state               VARCHAR(100),
    lga                 VARCHAR(100),
    risk_score          DOUBLE PRECISION NOT NULL,
    alert_level         VARCHAR(20) NOT NULL,
    expected_count_24h  DOUBLE PRECISION NOT NULL,
    trend_direction     VARCHAR(10) NOT NULL,
    peak_time           VARCHAR(30),
    contributing_factors VARCHAR(500),
    forecast_time       TIMESTAMP NOT NULL,
    created_at          TIMESTAMP NOT NULL DEFAULT NOW(),
    model_version       VARCHAR(20)
);

-- Indexes for common query patterns
CREATE INDEX IF NOT EXISTS idx_prediction_cell
    ON predictions (cell_lat, cell_lng);

CREATE INDEX IF NOT EXISTS idx_prediction_forecast_time
    ON predictions (forecast_time);

CREATE INDEX IF NOT EXISTS idx_prediction_risk_score
    ON predictions (risk_score DESC);

CREATE INDEX IF NOT EXISTS idx_prediction_created_at
    ON predictions (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_prediction_alert_level
    ON predictions (alert_level);

CREATE INDEX IF NOT EXISTS idx_prediction_state
    ON predictions (state);

-- Add comment for documentation
COMMENT ON TABLE predictions IS 'ML model predictions for terrorist activity forecasting';
COMMENT ON COLUMN predictions.cell_lat IS 'Latitude of the 0.1-degree grid cell center';
COMMENT ON COLUMN predictions.cell_lng IS 'Longitude of the 0.1-degree grid cell center';
COMMENT ON COLUMN predictions.risk_score IS 'Risk score 0.0–1.0 from the ML model';
COMMENT ON COLUMN predictions.alert_level IS 'Alert level: Normal, Elevated, High, Severe, Critical';
COMMENT ON COLUMN predictions.expected_count_24h IS 'Predicted incident count for the next 24 hours';
COMMENT ON COLUMN predictions.trend_direction IS 'Trend: rising, falling, or stable';
COMMENT ON COLUMN predictions.peak_time IS 'Peak time for predicted activity (ISO-8601)';
COMMENT ON COLUMN predictions.contributing_factors IS 'Comma-separated list of contributing factors';
COMMENT ON COLUMN predictions.forecast_time IS 'The forecast time this prediction applies to';
COMMENT ON COLUMN predictions.model_version IS 'Version of the ML model that generated this prediction';
